import {integer, suggestQuery} from '@crew/shared';
import {registerSearchIndex} from './search-index.js';
import {searchAccess, searchIssues} from './search.js';

export function suggestionCatalog(ctx, access) {
  const allowed = new Set(access.projectIds);
  const projects = ctx.db.prepare('SELECT id,key,name FROM projects WHERE org_id=? ORDER BY key,id').all(access.orgId).filter(row => allowed.has(row.id));
  const statuses = [];
  const labels = [];
  const assignees = new Map();
  for (const project of projects) {
    for (const status of ctx.db.prepare('SELECT name,category FROM project_statuses WHERE project_id=? ORDER BY position').all(project.id)) statuses.push({value: status.name, label: status.name, description: project.key + ' · ' + status.category});
    for (const label of ctx.db.prepare('SELECT id,name FROM labels WHERE project_id=? ORDER BY name').all(project.id)) labels.push({value: label.name, label: label.name, description: project.key});
    const members = ctx.db.prepare('SELECT u.id,u.name,u.email FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.org_id=? ORDER BY u.name,u.id').all(access.orgId);
    for (const user of members) {
      if (ctx.permissions.canProject(user.id, project.id, 'project:read')) assignees.set(user.id, {value: user.id, label: user.name, description: user.email});
    }
  }
  return {projects: projects.map(project => ({value: project.key, label: project.key, description: project.name})), statuses, labels, assignees: [...assignees.values()]};
}

export function registerSearchRoutes(ctx) {
  registerSearchIndex(ctx);
  const {app, requireAuth} = ctx;
  app.get('/api/v1/search/catalog', requireAuth, (req, res) => {
    const access = searchAccess(ctx, req);
    res.json(suggestionCatalog(ctx, access));
  });
  app.get('/api/v1/search', requireAuth, (req, res) => res.json(searchIssues(ctx, req)));
  app.get('/api/v1/search/suggestions', requireAuth, (req, res) => {
    const access = searchAccess(ctx, req);
    const source = String(req.query.q ?? '').slice(0, 4000);
    const caret = integer(req.query.caret ?? source.length, 'caret', {min: 0, max: source.length});
    res.json({items: suggestQuery(source, suggestionCatalog(ctx, access), caret)});
  });
}

