import {parseQuery} from './parser.js';
import {quoteQueryValue} from './suggestions.js';
import {validatedQuery} from '../schemas/query.js';

export const QUERY_FIELD_DEFINITIONS = Object.freeze([
  {field: 'text', label: 'Free text', operators: ['prefix', 'phrase'], placeholder: 'Search words or an exact phrase'},
  {field: 'status', label: 'Status', operators: [':', '!='], catalog: 'statuses', placeholder: 'Status name, category or ID'},
  {field: 'assignee', label: 'Assignee', operators: [':', '!='], catalog: 'assignees', placeholder: '@me, unassigned or person'},
  {field: 'label', label: 'Label', operators: [':', '!='], catalog: 'labels', placeholder: 'Label name or ID'},
  {field: 'project', label: 'Project', operators: [':', '!='], catalog: 'projects', placeholder: 'Project key or ID'},
  {field: 'priority', label: 'Priority', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: '0 to 4'},
  {field: 'created', label: 'Created', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: 'YYYY-MM-DD or UTC ISO timestamp'},
  {field: 'updated', label: 'Updated', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: 'YYYY-MM-DD or UTC ISO timestamp'}
]);

const nodeId = () => globalThis.crypto.randomUUID();
export function newQueryCondition(field = 'status') {
  const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === field);
  if (!definition) throw new Error('Unknown builder field');
  return {id: nodeId(), type: 'condition', field, operator: definition.operators[0], value: '', negated: false};
}
export function newQueryGroup(mode = 'and') {
  return {id: nodeId(), type: 'group', mode, negated: false, children: []};
}

export function builderToQuery(root) {
  function serialize(node, isRoot = false) {
    let source;
    if (node.type === 'group') {
      if (!['and', 'or'].includes(node.mode)) throw new Error('Choose AND or OR for every group');
      if (!node.children.length) {
        if (isRoot && !node.negated) return '';
        throw new Error('Add a condition to every group, or remove the empty group');
      }
      source = '(' + node.children.map(child => serialize(child)).join(node.mode === 'and' ? ' AND ' : ' OR ') + ')';
    } else if (node.type === 'condition') {
      const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === node.field);
      if (!definition || !definition.operators.includes(node.operator)) throw new Error('Choose a supported operator for ' + node.field);
      const value = String(node.value).trim();
      if (!value) throw new Error('Enter a value for ' + definition.label);
      if (node.field === 'text') {
        source = node.operator === 'phrase' ? JSON.stringify(value) : value.split(/\s+/u).map(quoteQueryValue).join(' AND ');
        if (node.operator === 'prefix' && /\s/u.test(value)) source = '(' + source + ')';
      } else source = node.field + node.operator + quoteQueryValue(value);
    } else throw new Error('Unknown query builder node');
    return node.negated ? 'NOT ' + source : source;
  }
  return validatedQuery(serialize(root, true)).query;
}

export function queryToBuilder(source = '') {
  const ast = parseQuery(validatedQuery(source).query);
  function convert(node) {
    if (node.type === 'all') return newQueryGroup();
    if (node.type === 'not') return {...convert(node.child), negated: true};
    if (node.type === 'and' || node.type === 'or') {
      const left = convert(node.left), right = convert(node.right);
      const flatten = child => child.type === 'group' && !child.negated && child.mode === node.type ? child.children : [child];
      return {...newQueryGroup(node.type), children: [...flatten(left), ...flatten(right)]};
    }
    if (node.type === 'term') return {...newQueryCondition('text'), operator: node.quoted ? 'phrase' : 'prefix', value: node.value};
    const operator = node.operator === '=' ? ':' : node.operator;
    return {...newQueryCondition(node.field), operator, value: String(node.value)};
  }
  const result = convert(ast);
  return result.type === 'group' ? result : {...newQueryGroup(), children: [result]};
}

export function updateQueryNode(root, id, change) {
  if (root.id === id) return typeof change === 'function' ? change(root) : {...root, ...change};
  if (root.type !== 'group') return root;
  return {...root, children: root.children.map(child => updateQueryNode(child, id, change))};
}

export function removeQueryNode(root, id) {
  if (root.id === id) return newQueryGroup();
  if (root.type !== 'group') return root;
  return {...root, children: root.children.filter(child => child.id !== id).map(child => removeQueryNode(child, id))};
}

export function moveQueryChild(root, groupId, from, to) {
  return updateQueryNode(root, groupId, group => {
    if (group.type !== 'group' || from < 0 || to < 0 || from >= group.children.length || to >= group.children.length) return group;
    const children = [...group.children];
    const [moving] = children.splice(from, 1);
    children.splice(to, 0, moving);
    return {...group, children};
  });
}

export function conditionChoices(field, catalog = {}) {
  if (field === 'priority') return [0, 1, 2, 3, 4].map(value => ({value: String(value), label: String(value)}));
  const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === field);
  const values = definition?.catalog ? catalog[definition.catalog] ?? [] : [];
  const all = field === 'assignee' ? [{value: '@me', label: 'Assigned to me'}, {value: 'unassigned', label: 'Unassigned'}, ...values] : values;
  return [...new Map(all.map(item => [String(item.value), item])).values()];
}

import {useState} from 'preact/hooks';
import {Button, Field, Notice, Loading, useLoad} from '../../components/ui.jsx';
import {QUERY_FIELD_DEFINITIONS, newQueryCondition, newQueryGroup, queryToBuilder, builderToQuery,
  updateQueryNode, removeQueryNode, moveQueryChild, conditionChoices} from '../../../../shared/src/index.js';

function Condition({node, catalog, update}) {
  const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === node.field);
  const choices = conditionChoices(node.field, catalog);
  const listId = 'builder-values-' + node.id;
  function changeField(field) {
    const next = QUERY_FIELD_DEFINITIONS.find(item => item.field === field);
    update(node.id, {field, operator: next.operators[0], value: ''});
  }
  return <div className="query-condition">
    <Field label="Field"><select value={node.field} onChange={event => changeField(event.currentTarget.value)}>
      {QUERY_FIELD_DEFINITIONS.map(item => <option key={item.field} value={item.field}>{item.label}</option>)}
    </select></Field>
    <Field label="Operator"><select value={node.operator} onChange={event => update(node.id, {operator: event.currentTarget.value})}>
      {definition.operators.map(operator => <option key={operator} value={operator}>{operator === ':' ? 'is' : operator === '!=' ? 'is not' : operator}</option>)}
    </select></Field>
    <Field label="Value"><input value={node.value} list={choices.length ? listId : undefined}
      type={node.field === 'priority' ? 'number' : 'text'} min={node.field === 'priority' ? 0 : undefined} max={node.field === 'priority' ? 4 : undefined}
      placeholder={definition.placeholder} onInput={event => update(node.id, {value: event.currentTarget.value})}/></Field>
    {choices.length > 0 && <datalist id={listId}>{choices.map(item => <option key={String(item.value)} value={item.value}>{item.label}{item.description ? ' · ' + item.description : ''}</option>)}</datalist>}
    <label><input type="checkbox" checked={node.negated} onChange={event => update(node.id, {negated: event.currentTarget.checked})}/>NOT this condition</label>
  </div>;
}

function Group({node, depth = 0, catalog, update, remove, move}) {
  return <fieldset className="query-group">
    <legend>{depth ? 'Nested group' : 'Compound query'}</legend>
    <div className="actions">
      <label>Match <select aria-label="Group operator" value={node.mode} onChange={event => update(node.id, {mode: event.currentTarget.value})}>
        <option value="and">all conditions (AND)</option><option value="or">any condition (OR)</option>
      </select></label>
      <label><input type="checkbox" checked={node.negated} onChange={event => update(node.id, {negated: event.currentTarget.checked})}/>NOT this group</label>
    </div>
    {!node.children.length && <p>Add a condition to start. An empty root query matches all accessible issues.</p>}
    {node.children.map((child, index) => <div className="query-builder-row" key={child.id}>
      {child.type === 'group' ? <Group node={child} depth={depth + 1} catalog={catalog} update={update} remove={remove} move={move}/>
        : <Condition node={child} catalog={catalog} update={update}/>}
      <div className="actions">
        <Button type="button" disabled={index === 0} onClick={() => move(node.id, index, index - 1)}>Move up</Button>
        <Button type="button" disabled={index === node.children.length - 1} onClick={() => move(node.id, index, index + 1)}>Move down</Button>
        <Button type="button" onClick={() => remove(child.id)}>Remove {child.type === 'group' ? 'group' : 'condition'}</Button>
      </div>
    </div>)}
    <div className="actions">
      <Button type="button" onClick={() => update(node.id, group => ({...group, children: [...group.children, newQueryCondition()]}))}>Add condition</Button>
      <Button type="button" disabled={depth >= 62} onClick={() => update(node.id, group => ({...group, children: [...group.children, newQueryGroup()]}))}>Add group</Button>
    </div>
  </fieldset>;
}

export function QueryBuilder({api, orgId, projectId, query, onApply, onSearch}) {
  const [root, setRoot] = useState(() => newQueryGroup());
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const catalog = useLoad(() => orgId ? api.get('/search/catalog?' + new URLSearchParams({orgId, ...(projectId ? {projectId} : {})})) : {}, [orgId, projectId]);
  let preview = '', previewError = null;
  try {preview = builderToQuery(root);} catch (invalid) {previewError = invalid;}
  const update = (id, change) => {setRoot(previous => updateQueryNode(previous, id, change)); setMessage('');};
  const remove = id => {setRoot(previous => removeQueryNode(previous, id)); setMessage('');};
  const move = (id, from, to) => setRoot(previous => moveQueryChild(previous, id, from, to));
  function loadQuery() {
    try {setRoot(queryToBuilder(query)); setError(null); setMessage('Loaded the editor query into the builder.');}
    catch (invalid) {setError(invalid);}
  }
  function apply(search = false) {
    try {
      const source = builderToQuery(root);
      onApply(source);
      if (search) onSearch(source);
      setError(null);
      setMessage(search ? 'Builder query submitted.' : 'Applied the builder query to the editor.');
    } catch (invalid) {setError(invalid);}
  }
  return <details className="query-builder"><summary>Build a compound query with fields and groups</summary>
    <Notice error={error ?? catalog.error}/><Notice>{message}</Notice>
    <p>Add typed conditions, group them with AND/OR, and negate a condition or group. Values come from projects you can currently read.</p>
    <div className="actions"><Button type="button" onClick={loadQuery}>Load editor query</Button>
      <Button type="button" onClick={() => {setRoot(newQueryGroup()); setMessage('Builder cleared. The editor is unchanged.');}}>Clear builder</Button>
      <Button type="button" onClick={catalog.reload}>Refresh values</Button></div>
    {catalog.loading ? <Loading/> : <Group node={root} catalog={catalog.data ?? {}} update={update} remove={remove} move={move}/>}
    {previewError ? <Notice error={previewError}/> : <p>Preview: <code>{preview || 'All accessible issues'}</code></p>}
    <div className="actions"><Button type="button" disabled={Boolean(previewError)} onClick={() => apply()}>Apply query to editor</Button>
      <Button type="button" disabled={!orgId || Boolean(previewError)} onClick={() => apply(true)}>Apply and search</Button></div>
  </details>;
}

import {useEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {QueryBuilder} from './query-builder.jsx';
import {QueryEditor} from './query-editor.jsx';
import {useLiveUpdates} from '../../live.js';
import {pagingRequest, searchLocation, appendQueryFilter, nextSearchPage, previousSearchPage, searchSnapshot, sameSearch} from './search-state.js';

export function Highlight({segments = []}) {
  return <>{segments.map((part, index) => part.match ? <mark key={index}>{part.text}</mark> : <span key={index}>{part.text}</span>)}</>;
}

export function SearchHelp() {
  return <details><summary>Query language and examples</summary>
    <p>Use words for token prefixes, or quotes for an exact phrase. Adjacent terms mean AND. NOT binds before AND, then OR. Parentheses override precedence.</p>
    <ul>
      <li><code>status:active AND assignee:@me</code> · my active issues</li>
      <li><code>project:APP AND (label:bug OR priority&gt;=3)</code> · urgent work</li>
      <li><code>created&gt;2026-01-01 AND updated&lt;2027-01-01</code> · UTC date window</li>
      <li><code>"search index" AND NOT status:done</code> · exact phrase excluding completed work</li>
    </ul>
    <p>Filter values match exact IDs or names; quote names with spaces. Priority ranges from 0 to 4. Dates use YYYY-MM-DD; quote full UTC ISO timestamps.</p>
  </details>;
}

export function SearchPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [input, setInput] = useState(query.q ?? '');
  const [projectId, setProjectId] = useState(query.projectId ?? '');
  const [results, setResults] = useState(null);
  const [applied, setApplied] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [stale, setStale] = useState(false);
  const [history, setHistory] = useState(['']);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState('');
  const inputRef = useRef(null);
  const requestVersion = useRef(0);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: [], projects: []}, [orgId]);
  useEffect(() => {
    if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);
  }, [organizations.data]);
  useEffect(() => {
    setOrgId(query.orgId ?? '');
    setInput(query.q ?? '');
    setProjectId(query.projectId ?? '');
    setResults(null);
    setHistory(['']);
    requestVersion.current++;
    setApplied(null);
    if (query.orgId && query.q !== undefined) run(null, [''], searchSnapshot(query.orgId, query.q, query.projectId ?? ''));
  }, [query.orgId, query.q, query.projectId]);
  useEffect(() => () => {requestVersion.current++;}, []);
  const live = useLiveUpdates({orgId, projectId, enabled: Boolean(orgId), onActivity: () => setStale(true)});
  async function run(event, nextHistory = [''], submitted = searchSnapshot(orgId, input, projectId)) {
    event?.preventDefault();
    const version = ++requestVersion.current;
    setBusy(true);
    setError(null);
    setSaved('');
    try {
      const path = pagingRequest(submitted, nextHistory.at(-1));
      const data = await api.get(path);
      if (version !== requestVersion.current) return;
      setResults(data);
      setApplied(submitted);
      setHistory(nextHistory);
      setStale(false);
    } catch (failure) {if (version === requestVersion.current) {setError(failure); setResults(null);}}
    finally {if (version === requestVersion.current) setBusy(false);}
  }
  function clearResults() {
    requestVersion.current++;
    setResults(null);
    setApplied(null);
    setHistory(['']);
    setBusy(false);
    setError(null);
  }
  const draftChanged = applied && !sameSearch(applied, searchSnapshot(orgId, input, projectId));
  return <Page title="Search issues" actions={<a href={routeLink('/filters', {orgId})}>Saved filters</a>}>
    <Notice error={organizations.error ?? options.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Create or join an organization to search its work.</Empty> : <>
      <form onSubmit={run}>
        <div className="search-controls">
          <Field label="Organization"><select value={orgId} onChange={event => {setOrgId(event.currentTarget.value); setProjectId(''); clearResults();}}>
            <option value="">Choose an organization</option>
            {organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
          </select></Field>
          <Field label="Project"><select value={projectId} onChange={event => {setProjectId(event.currentTarget.value); clearResults();}}>
            <option value="">All accessible projects</option>
            {(options.data?.projects ?? []).map(project => <option key={project.id} value={project.id}>{project.key} · {project.name}</option>)}
          </select></Field>
        </div>
        <QueryEditor api={api} orgId={orgId} projectId={projectId} value={input} onChange={setInput} inputRef={inputRef} error={error}/>
        <div className="actions"><Button busy={busy} disabled={!orgId} type="submit">Search</Button>
          <Button type="button" disabled={!orgId || busy} onClick={() => setSaving(true)}>Save search</Button>
          <Button type="button" onClick={() => {setInput(''); clearResults();}}>Clear</Button></div>
      </form>
      <Notice error={error}/><Notice>{saved}</Notice>
      <SearchHelp/>
      <QueryBuilder api={api} orgId={orgId} projectId={projectId} query={input} onApply={setInput}
        onSearch={source => run(null, [''], searchSnapshot(orgId, source, projectId))}/>
      <div className="actions"><span>Live updates: {live.status}</span><Button type="button" onClick={() => live.setPaused(!live.paused)}>{live.paused ? 'Resume updates' : 'Pause updates'}</Button>
        {stale && results && <Button type="button" busy={busy} onClick={event => run(event, [''], applied)}>Activity changed · refresh search</Button>}
      </div>
      {saving && <FilterForm key={orgId + input} api={api} orgId={orgId} filter={{query: input}} teams={options.data?.teams}
        onCancel={() => setSaving(false)} onSaved={filter => {setSaving(false); setSaved('Saved “' + filter.name + '”.');}}/>}
      {busy && <Loading/>}
      {results && <section aria-label="Search results">
        {draftChanged && <Notice>The query editor has unsent changes. These results and pages still use the last submitted query.</Notice>}
        <p>Results for <code>{applied?.query || 'all accessible issues'}</code></p>
        <h2>{results.total} {results.total === 1 ? 'issue' : 'issues'} found</h2>
        <div className="search-facets">{Object.entries(results.facets ?? {}).map(([field, values]) => <details key={field}>
          <summary>{field}</summary>{values.map(item => <Button key={String(item.value)} onClick={() => {setInput(appendQueryFilter(applied?.query ?? '', field, item.value)); setResults(null);}}>{String(item.value)} ({item.count})</Button>)}
        </details>)}</div>
        {!results.items.length ? <Empty>No accessible issues match this query. Try fewer filters or a shorter token prefix.</Empty> : <ol className="search-results">{results.items.map(issue => <li key={issue.id} data-testid={'search-result-' + issue.id}>
          <article><h3><a href={routeLink('/issues/' + issue.id)}>{issue.key} · <Highlight segments={issue.highlights.title}/></a></h3>
            <p><Highlight segments={issue.highlights.description}/></p>
            {issue.matchFields.includes('comments') && <p className="search-comment">Discussion: <Highlight segments={issue.highlights.comments}/></p>}
            <p>{issue.statusName} · priority {issue.priority} · {issue.assignee?.name ?? 'Unassigned'} · updated {new Date(issue.updatedAt).toLocaleString()}</p>
            <p>{issue.labels.map(label => <span className="label" key={label.id}>{label.name}</span>)}</p>
          </article>
        </li>)}</ol>}
        <div className="actions"><Button disabled={busy || history.length < 2} onClick={event => run(event, previousSearchPage(history), applied)}>Previous</Button>
          <span>Page {history.length}</span><Button disabled={busy || !results.nextCursor} onClick={event => run(event, nextSearchPage(history, results.nextCursor), applied)}>Next</Button></div>
        <a href={'#' + searchLocation(orgId, input, projectId)}>Link to this query</a>
      </section>}
    </>}
  </Page>;
}

